    private fun q(
        id: Int,
        subdomain: String,
        question: String,
        options: List<String>,
        answer: String
    ): GateQuestion {
        val topicId = when (subdomain) {
            "Basic Circuits & KCL-KVL" -> "nt_laws"
            "Network Theorems" -> "nt_theorems"
            "Transient Analysis" -> "nt_transients"
            "AC Steady-State Analysis" -> "nt_ac_steady"
            "Resonance & Coupled Circuits" -> "nt_resonance_coupled"
            "Two-Port Networks" -> "nt_twoport"
            "Network Graph Theory" -> "nt_graph"
            else -> "nt_laws"
        }

        val subtopicId = when (subdomain) {
            "Basic Circuits & KCL-KVL" -> "nt_laws_basics"
            "Network Theorems" -> "nt_theorems_active"
            "Transient Analysis" -> "nt_trans_response"
            "AC Steady-State Analysis" -> "nt_ac_steady_state"
            "Resonance & Coupled Circuits" -> "nt_resonance_coupled_circuits"
            "Two-Port Networks" -> "nt_parameters_twoport"
            "Network Graph Theory" -> "nt_graph_theory"
            else -> "nt_laws_basics"
        }

        val correctIdx = options.indexOf(answer).let { if (it == -1) 0 else it }

        val difficulty = when (id % 3) {
            0 -> "Easy"
            1 -> "Medium"
            else -> "Hard"
        }

        val formulas = when (subdomain) {
            "Basic Circuits & KCL-KVL" -> "Σ I_node = 0, Σ V_loop = 0"
            "Network Theorems" -> "V_th = I_n * R_th"
            "Transient Analysis" -> "τ = R * C (or L / R), x(t) = x(∞) + [x(0) - x(∞)] * e^(-t/τ)"
            "AC Steady-State Analysis" -> "S = P + jQ = V * I*"
            "Resonance & Coupled Circuits" -> "f_0 = 1 / (2 * π * sqrt(L * C))"
            "Two-Port Networks" -> "AD - BC = 1, Z11 = Z22"
            "Network Graph Theory" -> "B - N + 1"
            else -> ""
        }

        val explanationText = "Based on fundamental $subdomain concepts. The correct choice is: '$answer'. " +
            when (subdomain) {
                "Basic Circuits & KCL-KVL" -> "Evaluates fundamental Kirchhoff's Laws (KCL, KVL), network element equations (charge, energy conservation), source configurations, and parallel/series reductions."
                "Network Theorems" -> "Applies Thevenin's, Norton's, Superposition, Maximum Power Transfer, Tellegen's, Reciprocity, Miller's or Substitution Theorems to linear circuits."
                "Transient Analysis" -> "Solves first-order (RC, RL) or second-order (RLC) circuit differential or s-domain Laplace equations under switching conditions."
                "AC Steady-State Analysis" -> "Addresses phasor representation, complex impedance/admittance calculations, active, reactive, and apparent power, power factor, and three-phase parameters."
                "Resonance & Coupled Circuits" -> "Analyzes RLC series/parallel resonance, quality factor, selective bandwidths, magnetic coupling, coefficient of coupling, and mutual inductance polarities."
                "Two-Port Networks" -> "Uses Z, Y, h, g, and ABCD matrices to represent open-circuit, short-circuit, hybrid, or cascading transmission environments."
                "Network Graph Theory" -> "Utilizes network topology concepts including twigs, links, trees, fundamental tie-sets (loops), cut-sets, incidence matrices, and ranks."
                else -> ""
            }

        return GateQuestion(
            id = "nt_q_$id",
            subjectId = "network_theory",
            topicId = topicId,
            subtopicId = subtopicId,
            year = 2020 + (id % 7),
            questionText = question,
            questionType = QuestionType.MCQ,
            options = options,
            correctOptions = listOf(correctIdx),
            correctNumericalRange = null,
            explanation = explanationText,
            formulasUsed = formulas,
            shortcutTricks = "Analyze dimensions, signs, and asymptotic limits of standard formulas.",
            relatedConcepts = "Network Theory, circuit analysis, $subdomain",
            difficulty = difficulty
        )
    }
}
